      const result = compare(a, b, sortKey);
      return result !== 0 ? result * dir : b.id.localeCompare(a.id);
    });
  }, [filtered, sortKey, sortDir]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
