      setSortKey(key);
      setSortDir(key === "amount" || key === "date" ? "desc" : "asc");
    }
    setPage(1);
  }

  function clearFilters() {
    setStatus("all");
    setRange(undefined);
    setQuery("");
    setPage(1);
  }

  function goTo(p: number) {
    setPage(Math.min(Math.max(1, p), pageCount));
  }

  const rangeLabel = range?.from
    ? range.to && localToUTCDay(range.to) !== localToUTCDay(range.from)
      ? `${formatPickedDate(range.from)} – ${formatPickedDate(range.to)}`
      : formatPickedDate(range.from)
    : "Any date";

  const totalRevenue = React.useMemo(
    () =>
      filtered
        .filter((o) => o.status !== "refunded")
        .reduce((sum, o) => sum + o.amount, 0),
    [filtered],
  );

  const showingFrom = sorted.length === 0 ? 0 : startIndex + 1;
  const showingTo = Math.min(startIndex + pageSize, sorted.length);

  return (
    <main className="mx-auto w-full max-w-6xl px-4 py-8 sm:px-6 sm:py-12">
      <header className="mb-6 flex flex-col gap-1">
        <h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">
          Orders
        </h1>
        <p className="text-sm text-muted-foreground">
          Track, filter and review recent orders from the Trailhead Outfitters
          storefront.
        </p>
      </header>

      <Card className="gap-4 py-4 sm:py-6">
        <CardHeader className="gap-4">
          <div className="flex flex-col gap-1">
            <CardTitle className="text-base">Order history</CardTitle>
            <CardDescription>
              {filtered.length} {filtered.length === 1 ? "order" : "orders"}
              {" · "}
              {currencyFormatter.format(totalRevenue / 100)} net revenue
            </CardDescription>
          </div>

          {/* Filters row */}
          <div
            role="search"
            aria-label="Filter orders"
            className="flex flex-col gap-3 lg:flex-row lg:flex-wrap lg:items-end"
          >
            <div className="flex min-w-0 flex-col gap-1.5">
              <span
                id={statusLabelId}
                className="text-xs font-medium text-muted-foreground"
              >
                Status
              </span>
              <div className="max-w-full overflow-x-auto pb-1 -mb-1">
                <ToggleGroup
                  type="single"
                  variant="outline"
                  spacing={0}
                  value={status}
                  onValueChange={(value) => {
                    // Radix emits "" when the active item is clicked again; keep a selection.
                    if (!value) return;
                    setStatus(value as StatusFilter);
                    setPage(1);
                  }}
                  aria-labelledby={statusLabelId}
                >
                  {STATUS_OPTIONS.map((opt) => (
                    <ToggleGroupItem
                      key={opt.value}
                      value={opt.value}
                      aria-label={`${opt.label} orders`}
                    >
                      {opt.label}
                    </ToggleGroupItem>
                  ))}
                </ToggleGroup>
              </div>
            </div>

            <div className="flex flex-col gap-1.5">
              <span
                id={dateLabelId}
                className="text-xs font-medium text-muted-foreground"
              >
                Order date
              </span>
              <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    aria-labelledby={dateLabelId}
                    aria-haspopup="dialog"
                    className={cn(
                      "w-full justify-start font-normal lg:w-64",
                      !range?.from && "text-muted-foreground",
                    )}
                  >
                    <CalendarIcon aria-hidden="true" />
                    <span className="truncate">{rangeLabel}</span>
                  </Button>
                </PopoverTrigger>
                <PopoverContent
                  align="start"
                  className="w-auto max-w-[calc(100vw-2rem)] p-0"
                >
                  <Calendar
                    mode="range"
                    numberOfMonths={1}
                    defaultMonth={range?.from ?? new Date(2025, 2, 1)}
                    selected={range}
                    onSelect={(next) => {
                      setRange(next);
                      setPage(1);
                    }}
                    autoFocus
                  />
                  <div className="flex items-center justify-between gap-2 border-t p-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      disabled={!range?.from}
                      onClick={() => {
                        setRange(undefined);
                        setPage(1);
                      }}
                    >
                      Clear dates
                    </Button>
                    <Button size="sm" onClick={() => setCalendarOpen(false)}>
                      Done
                    </Button>
                  </div>
                </PopoverContent>
              </Popover>
            </div>

            <div className="flex min-w-0 flex-1 flex-col gap-1.5 lg:min-w-60">
              <Label
                htmlFor={searchId}
                className="text-xs font-medium text-muted-foreground"
              >
                Search
              </Label>
              <InputGroup>
                <InputGroupAddon>
                  <SearchIcon aria-hidden="true" />
                </InputGroupAddon>
                <InputGroupInput
                  id={searchId}
                  type="search"
                  value={query}
                  onChange={(e) => {
                    setQuery(e.target.value);
                    setPage(1);
                  }}
                  placeholder="Order, customer, email or product"
                  autoComplete="off"
                />
                {query && (
                  <InputGroupAddon align="inline-end">
                    <InputGroupButton
                      size="icon-xs"
                      aria-label="Clear search"
                      onClick={() => {
                        setQuery("");
                        setPage(1);
