        </CardHeader>

        <CardContent className="px-0 sm:px-6">
          <div className="border-y sm:rounded-md sm:border">
            <Table aria-describedby="orders-summary">
              <TableHeader>
                <TableRow className="hover:bg-transparent">
                  {COLUMNS.map((col) => {
                    const active = sortKey === col.key;
                    const ariaSort = active
                      ? sortDir === "asc"
                        ? "ascending"
                        : "descending"
                      : "none";
                    const Icon = !active
                      ? ArrowUpDownIcon
                      : sortDir === "asc"
                        ? ArrowUpIcon
                        : ArrowDownIcon;
                    return (
                      <TableHead
                        key={col.key}
                        aria-sort={ariaSort}
                        className={cn(
                          "px-2",
                          col.align === "right" && "text-right",
                          col.key === "id" && "pl-4 sm:pl-3",
                          col.key === "amount" && "pr-4 sm:pr-3",
                        )}
                      >
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => toggleSort(col.key)}
                          className={cn(
                            "-mx-2 h-8 px-2 font-medium",
                            col.align === "right" && "flex-row-reverse",
                          )}
                        >
                          {col.label}
                          <Icon
                            aria-hidden="true"
                            className={cn(
                              "size-3.5",
                              active ? "opacity-100" : "opacity-40",
                            )}
                          />
                          <span className="sr-only">
                            {active
                              ? `, sorted ${sortDir === "asc" ? "ascending" : "descending"}. Activate to reverse.`
                              : ", not sorted. Activate to sort ascending."}
                          </span>
                        </Button>
                      </TableHead>
                    );
                  })}
                </TableRow>
              </TableHeader>
              <TableBody>
                {pageRows.length > 0 ? (
