                    e.preventDefault();
                    goTo(currentPage - 1);
                  }}
                />
              </PaginationItem>
              {getPageItems(currentPage, pageCount).map((p, i) =>
                p === null ? (
                  <PaginationItem key={`gap-${i}`} className="hidden sm:block">
                    <PaginationEllipsis />
                  </PaginationItem>
                ) : (
                  <PaginationItem
                    key={p}
                    className={cn(
                      p !== currentPage &&
                        p !== 1 &&
                        p !== pageCount &&
                        "hidden sm:block",
                    )}
                  >
                    <PaginationLink
                      href="#"
                      isActive={p === currentPage}
                      aria-label={`Go to page ${p}`}
                      onClick={(e) => {
                        e.preventDefault();
                        goTo(p);
                      }}
                    >
                      {p}
                    </PaginationLink>
                  </PaginationItem>
                ),
              )}
              <PaginationItem>
                <PaginationNext
                  href="#"
                  aria-disabled={currentPage === pageCount}
                  tabIndex={currentPage === pageCount ? -1 : undefined}
                  className={cn(
                    currentPage === pageCount && "pointer-events-none opacity-50",
                  )}
                  onClick={(e) => {
                    e.preventDefault();
                    goTo(currentPage + 1);
                  }}
                />
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      </Card>
    </main>
  );
}
